"""Search plausible English-filter definitions against the paper's three counts.

Paper targets: 272 removed from 16859 -> 16587 kept; 16575 rows with a primary
emoji; 62 emojis with >=15 occurrences covering 15569 tweets.
"""
import collections
import re

import emoji
import numpy as np
import pandas as pd

RAW = "repo/Data/Final_Dataset_Twitter.csv"
SKIN = set(range(0x1F3FB, 0x1F400)) | {0xFE0F}


def canon(e):
    return "".join(c for c in e if ord(c) not in SKIN)


def primary(t):
    ms = [canon(x["emoji"]) for x in emoji.emoji_list(t)]
    ms = [m for m in ms if m]
    return ms[0] if ms else None


def clean(t):
    t = t.lower()
    t = re.sub(r"http\S+|www\.\S+", " ", t)
    t = re.sub(r"@\w+", " ", t)
    t = re.sub(r"#(\w+)", r"\1", t)
    return re.sub(r"\s+", " ", t).strip()


def make_num(kind, t, te):
    if kind == "aalpha":
        return sum(1 for c in t if c.isascii() and c.isalpha())
    if kind == "aalpha_clean":
        return sum(1 for c in t.lower() if c.isascii() and c.isalpha())
    if kind == "te_aalpha":
        return sum(1 for c in te if c.isascii() and c.isalpha())
    if kind == "ascii_nonws":
        return sum(1 for c in te if c.isascii() and not c.isspace())
    if kind == "alnum":
        return sum(1 for c in te if c.isascii() and c.isalnum())
    raise KeyError(kind)


def make_den(kind, t, te):
    if kind == "alpha":
        return sum(1 for c in t if c.isalpha())
    if kind == "te_alpha":
        return sum(1 for c in te if c.isalpha())
    if kind == "te_nonws":
        return sum(1 for c in te if not c.isspace())
    if kind == "te_len":
        return len(te)
    if kind == "nonws":
        return sum(1 for c in t if not c.isspace())
    if kind == "len":
        return len(t)
    if kind == "alnum":
        return sum(1 for c in t if c.isalnum())
    raise KeyError(kind)


def main():
    df = pd.read_csv(RAW)
    raw = [str(x) for x in df["Comments"]]
    pres = []
    for t in raw:
        te = emoji.replace_emoji(t, replace="")
        tc = clean(t)
        tce = emoji.replace_emoji(tc, replace="")
        pres.append((t, te, tc, tce))

    num_kinds = ["aalpha", "te_aalpha", "ascii_nonws", "alnum"]
    den_kinds = ["alpha", "te_alpha", "te_nonws", "te_len", "nonws", "len", "alnum"]
    rows = []
    for nk in num_kinds:
        for dk in den_kinds:
            vals = []
            for (t, te, tc, tce) in pres:
                n = make_num(nk, t, te)
                d = make_den(dk, t, te)
                vals.append(n / d if d > 0 else 0.0)
            v = np.array(vals)
            for thr in (0.85,):
                keep = v >= thr
                kept_idx = np.where(keep)[0]
                removed = int((~keep).sum())
                prim = [primary(raw[i]) for i in kept_idx]
                with_e = sum(1 for p in prim if p)
                cnt = collections.Counter(p for p in prim if p)
                panel = [e for e, c in cnt.items() if c >= 15]
                rows.append(dict(num=nk, den=dk, thr=thr, removed=removed,
                                 kept=int(keep.sum()), with_emoji=with_e,
                                 panel=len(panel), panel_tweets=sum(cnt[e] for e in panel)))
    rows.sort(key=lambda r: abs(r["removed"] - 272) + abs(r["with_emoji"] - 16575)
              + abs(r["panel_tweets"] - 15569))
    for r in rows[:12]:
        print(r)


if __name__ == "__main__":
    main()

